    "context.situation": "In this simulated URL-preview service, concerns were raised about fetch and redirect destinations supplied by users. Compare normal external-page retrieval with the traffic recorded on the server side.",
    "context.objective": "Practice distinguishing an incoming HTTP request from the server-side URL fetch it triggers. Correlate the initial URL, name resolution, redirects, and final retrieval outcome within the supplied evidence.",
    "context.period": "2026/08/12 16:00:00–2026/08/12 16:07:08 UTC (observation window of the supplied logs; Japan time is UTC+9)",
    "context.hosts.0.role": "Host represented in URL-preview request and fetch logs",
