    "tasks.0.prompt": "Which acting account appears in both sudo and the file-modification audit?",
    "tasks.0.placeholder": "Enter a value",
    "tasks.0.explanation": "The sudo caller matches the audit actor. root is the effective privilege identity, distinct from the original actor.",
    "tasks.0.hints.0.text": "Filter the relevant events.",
    "tasks.0.hints.1.text": "Correlate and count records using matching IDs or fields.",
