    "tasks.4.placeholder": "Enter a value",
    "tasks.4.explanation": "Only two later appends remain; the preceding 20 normal lines are absent.",
    "tasks.4.hints.0.text": "Filter the relevant events.",
    "tasks.4.hints.1.text": "Correlate and count records using matching IDs or fields.",
    "tasks.5.label": "Separately collected request count",
    "tasks.5.prompt": "How many total requests remain in the separately collected log?",
