    "tasks.5.explanation": "The 60 normal requests and two later requests are preserved. Two local lines do not mean only two requests occurred.",
    "tasks.5.hints.0.text": "Filter the relevant events.",
    "tasks.5.hints.1.text": "Correlate and count records using matching IDs or fields.",
    "tasks.6.label": "Effective execution privileges",
    "tasks.6.prompt": "What is the numeric euid at file_truncate time?",
    "tasks.6.placeholder": "Enter a value",
    "tasks.6.explanation": "The operation has euid=0. Distinguish it from auid=1005, which identifies the original login identity.",
