    "tasks.6.hints.1.text": "Correlate and count records using matching IDs or fields.",
    "tasks.7.label": "Process performing the operation",
    "tasks.7.prompt": "Which pid actually performed file_truncate?",
    "tasks.7.placeholder": "Enter a value",
    "tasks.7.explanation": "Its ppid=9020 matches the process number in the sudo log.",
    "tasks.7.hints.0.text": "Filter the relevant events.",
    "tasks.7.hints.1.text": "Correlate and count records using matching IDs or fields.",
