    "tasks.9.hints.0.text": "Filter the relevant events.",
    "tasks.9.hints.1.text": "Correlate and count records using matching IDs or fields.",
    "walkthrough.0.title": "Compare local and independently collected counts",
    "walkthrough.0.explanation": "After the attack, the counts are two versus 62 lines. Keep the storage locations distinct.",
    "walkthrough.1.title": "Inspect parent-child links between sudo and audit records",
    "walkthrough.1.explanation": "Correlate the actor, ppid, effective privileges, and size change to zero bytes.",
    "context.situation": "For this simulated Linux server, check for inconsistencies between action records and preserved logs. Compare normal administration and log management to investigate possible missing or modified records.",
    "context.objective": "Practice correlating authentication and privileged-action audits with existing logs and preserved material. Missing records alone do not prove an event never occurred; check what each source retains.",
    "context.period": "2026/08/12 18:00:00–2026/08/12 18:08:01 UTC (observation window of the supplied logs; Japan time is UTC+9)",
